sketch.css:
.qb{box-sizing:border-box;width:100%;height:100%;display:flex;flex-direction:column;gap:8px;padding:10px 12px;background:var(--window);color:var(--text);font:13px/1.4 "Segoe UI",system-ui,sans-serif;overflow:hidden;container-type:inline-size}
.qb *{box-sizing:border-box}
.summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px}
.stat{display:flex;align-items:baseline;gap:6px;padding:4px 10px;border-radius:8px;background:var(--background);min-width:0;overflow:hidden}
.stat .n{font-size:18px;font-weight:700;letter-spacing:-.02em;line-height:1.2}
.stat .l{color:var(--muted);font-size:11.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.stat.released .n{color:var(--positive)}
.stat.hold .n{color:var(--warning)}
.stat.fail .n{color:var(--negative)}
.stat.coa .n{color:var(--accent)}
.chips{display:flex;gap:4px;flex-wrap:wrap}
.chip{padding:2px 10px;border-radius:12px;font-size:12px;font-weight:500;color:var(--muted);border:1px solid var(--border);cursor:pointer;white-space:nowrap}
.chip:hover{background:var(--hover);color:var(--text)}
.chip.selected{background:var(--accent);border-color:var(--accent);color:#fff}
.chip .c{opacity:.75;margin-left:4px;font-variant-numeric:tabular-nums}
.table{flex:1;min-height:0;display:flex;flex-direction:column;border-top:1px solid var(--border)}
.head{display:flex;align-items:center;gap:8px;padding:5px 6px;padding-right:20px;color:var(--muted);font-size:11px;font-weight:600;text-transform:uppercase;letter-spacing:.03em}
.rows{flex:1;min-height:0;overflow-y:scroll;overflow-x:hidden}
.row{display:flex;align-items:center;gap:8px;padding:5px 6px;border-radius:6px;cursor:pointer}
.row:hover{background:var(--hover)}
.row.selected{background:var(--hover);box-shadow:inset 3px 0 0 var(--accent)}
.id{flex:1;min-width:0}
.lot{font-weight:600;white-space:nowrap}
.meta{color:var(--muted);font-size:11.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.dots{display:none;gap:3px;margin-top:2px}
.dot{width:8px;height:8px;border-radius:50%;background:var(--positive)}
.dot.warn{background:var(--warning)}
.dot.bad{background:var(--negative)}
.dot.none{background:var(--border)}
.tests{display:flex;gap:4px}
.cell,.th{width:54px;text-align:center;flex:none}
.cell{padding:2px 0;border-radius:5px;font-size:12px;font-weight:600;font-variant-numeric:tabular-nums;color:var(--positive);background:color-mix(in srgb,var(--positive) 12%,transparent)}
.cell.warn{color:var(--warning);background:color-mix(in srgb,var(--warning) 16%,transparent)}
.cell.bad{color:var(--negative);background:color-mix(in srgb,var(--negative) 14%,transparent)}
.cell.none{color:var(--muted);background:transparent;font-weight:400}
.status{width:70px;flex:none;text-align:center;padding:1px 0;border-radius:10px;font-size:11.5px;font-weight:600}
.status.released{color:var(--positive);background:color-mix(in srgb,var(--positive) 14%,transparent)}
.status.hold{color:var(--warning);background:color-mix(in srgb,var(--warning) 18%,transparent)}
.status.fail{color:var(--negative);background:color-mix(in srgb,var(--negative) 14%,transparent)}
.status.pending{color:var(--muted);background:var(--background)}
.coa{width:20px;flex:none;display:flex;justify-content:center}
.coa svg{width:16px;height:16px}
.coa.yes{color:var(--accent)}
.coa.no{color:var(--border)}
.detail{margin:2px 6px 6px 9px;padding:8px 10px;border-radius:8px;background:var(--background);display:flex;flex-direction:column;gap:3px}
.dhead{display:flex;justify-content:space-between;font-size:12px;color:var(--muted);margin-bottom:2px}
.dhead b{color:var(--text)}
.drow{display:grid;grid-template-columns:1fr 90px 120px 14px;gap:8px;align-items:center;font-size:12px}
.drow .t{color:var(--muted)}
.drow .v{font-weight:600;font-variant-numeric:tabular-nums}
.drow .v.warn{color:var(--warning)}
.drow .v.bad{color:var(--negative)}
.drow .v.ok{color:var(--positive)}
.drow .s{color:var(--muted);font-variant-numeric:tabular-nums}
.drow .m{width:8px;height:8px;border-radius:50%;background:var(--positive)}
.drow .m.warn{background:var(--warning)}
.drow .m.bad{background:var(--negative)}
.drow .m.none{background:var(--border)}
.empty{color:var(--muted);text-align:center;padding:20px 0;font-size:12px}
@container (max-width:560px){
  .tests,.th{display:none}
  .head .tests{display:none}
  .dots{display:flex}
  .stat .l{font-size:11px}
}
@container (max-width:420px){
  .coa{display:none}
  .status{width:60px}
  .drow{grid-template-columns:1fr 80px 100px 14px}
}

