function render(root, props, fire) {
  const esc = s => String(s == null ? '' : s).replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  const lots = Array.isArray(props.lots) ? props.lots : [];
  const specs = (Array.isArray(props.specs) ? props.specs : []).filter(s => s && s.test);
  const filter = (props.statusFilter || 'all').toLowerCase();
  const selected = props.selected || '';
  const num = v => (v === null || v === undefined || v === '' || isNaN(+v)) ? null : +v;
  const fmt = v => v === null ? '—' : (Math.abs(v) >= 100 ? v.toFixed(1) : Math.abs(v) >= 1 ? v.toFixed(2).replace(/\.?0+$/, '') : v.toFixed(3).replace(/\.?0+$/, '') || '0');
  const STATUS = ['released', 'hold', 'fail', 'pending'];
  const LABEL = { released: 'Released', hold: 'Hold', fail: 'Fail', pending: 'Pending' };
  const norm = s => { s = String(s || '').toLowerCase(); return STATUS.indexOf(s) >= 0 ? s : 'pending'; };

  function parse(str) {
    const o = {};
    String(str || '').split(';').forEach(p => { const i = p.indexOf('='); if (i > 0) { const v = num(p.slice(i + 1).trim()); if (v !== null) o[p.slice(0, i).trim().toLowerCase()] = v; } });
    return o;
  }
  // state of a value against its spec: ok | warn (within 10% of a limit) | bad | none
  function state(spec, v) {
    if (v === undefined || v === null) return 'none';
    const lo = num(spec.min), hi = num(spec.max);
    if ((lo !== null && v < lo) || (hi !== null && v > hi)) return 'bad';
    const m = (lo !== null && hi !== null) ? (hi - lo) * 0.1 : 0.1 * Math.abs(lo !== null ? lo : hi !== null ? hi : 0);
    if ((lo !== null && v - lo <= m) || (hi !== null && hi - v <= m)) return 'warn';
    return 'ok';
  }
  const specText = s => { const lo = num(s.min), hi = num(s.max); return lo !== null && hi !== null ? lo + ' – ' + hi : hi !== null ? '≤ ' + hi : lo !== null ? '≥ ' + lo : ''; };

  const items = lots.filter(l => l && l.lot).map(l => ({ l: l, st: norm(l.status), r: parse(l.results) }));
  const count = st => items.filter(i => i.st === st).length;
  const awaiting = items.filter(i => i.st === 'released' && !i.l.coaIssued).length;

  root.querySelector('.summary').innerHTML =
    '<div class="stat released"><span class="n">' + count('released') + '</span><span class="l">Released</span></div>' +
    '<div class="stat hold"><span class="n">' + count('hold') + '</span><span class="l">On hold</span></div>' +
    '<div class="stat fail"><span class="n">' + count('fail') + '</span><span class="l">Failed</span></div>' +
    '<div class="stat coa"><span class="n">' + awaiting + '</span><span class="l">Awaiting CoA</span></div>';

  const chips = root.querySelector('.chips');
  chips.innerHTML = ['all'].concat(STATUS).map(s => {
    const c = s === 'all' ? items.length : count(s);
    return '<span class="chip' + (s === filter ? ' selected' : '') + '" data-s="' + s + '">' + (s === 'all' ? 'All' : LABEL[s]) + '<span class="c">' + c + '</span></span>';
  }).join('');
  chips.querySelectorAll('.chip').forEach(el => el.onclick = () => fire('statusFilterChanged', { status: el.dataset.s, statusFilter: el.dataset.s }));

  const short = { proof: 'Proof', water: 'Water', methanol: 'MeOH', acidity: 'Acid', appearance: 'Appear' };
  const label = s => short[String(s.test).toLowerCase()] || s.test;
  root.querySelector('.head').innerHTML = '<span class="id">Lot</span><span class="tests">' +
    specs.map(s => '<span class="th" title="' + esc(s.test + (s.unit ? ' (' + s.unit + ')' : '')) + '">' + esc(label(s)) + '</span>').join('') +
    '</span><span class="status">Status</span><span class="coa">CoA</span>';

  const check = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="M4 1.75h5.5L13 5.25v9H4z"/><path d="M9.5 1.75v3.5H13"/><path d="M6 10l1.6 1.6L10.8 8.2"/></svg>';
  const blank = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="2 2"><path d="M4 1.75h5.5L13 5.25v9H4z"/></svg>';

  const shown = items.filter(i => filter === 'all' || i.st === filter);
  const rows = root.querySelector('.rows');
  if (!shown.length) { rows.innerHTML = '<div class="empty">No lots</div>'; return; }
  rows.innerHTML = shown.map(i => {
    const l = i.l, sel = l.lot === selected;
    const cells = specs.map(s => { const v = i.r[String(s.test).toLowerCase()]; return { s: s, v: v, st: state(s, v) }; });
    let h = '<div class="row' + (sel ? ' selected' : '') + '" data-lot="' + esc(l.lot) + '">' +
      '<div class="id"><div class="lot">' + esc(l.lot) + '</div><div class="meta">' +
      [l.plant, l.grade, l.vessel, String(l.sampled || '').replace('T', ' ').slice(5, 16)].filter(Boolean).map(esc).join(' · ') + '</div>' +
      '<div class="dots">' + cells.map(c => '<span class="dot ' + (c.st === 'ok' ? '' : c.st) + '"></span>').join('') + '</div></div>' +
      '<div class="tests">' + cells.map(c => '<span class="cell ' + (c.st === 'ok' ? '' : c.st) + '">' + (c.v === undefined ? '—' : fmt(c.v)) + '</span>').join('') + '</div>' +
      '<span class="status ' + i.st + '">' + LABEL[i.st] + '</span>' +
      '<span class="coa ' + (l.coaIssued ? 'yes' : 'no') + '" title="' + (l.coaIssued ? 'CoA issued' : 'CoA not issued') + '">' + (l.coaIssued ? check : blank) + '</span></div>';
    if (sel) {
      h += '<div class="detail"><div class="dhead"><span><b>' + esc(l.lot) + '</b> · ' + esc(l.grade) + ' · ' + esc(l.vessel) + '</span><span>' + (l.coaIssued ? 'CoA issued' : 'CoA not issued') + '</span></div>' +
        cells.map(c => '<div class="drow"><span class="t">' + esc(c.s.test) + '</span><span class="v ' + c.st + '">' + (c.v === undefined ? 'not tested' : fmt(c.v) + ' ' + esc(c.s.unit || '')) + '</span><span class="s">' + esc(specText(c.s)) + '</span><span class="m ' + (c.st === 'ok' ? '' : c.st) + '"></span></div>').join('') + '</div>';
    }
    return h;
  }).join('');
  rows.querySelectorAll('.row').forEach(el => el.onclick = () => { const v = el.dataset.lot === selected ? '' : el.dataset.lot; fire('lotSelected', { lot: v, selected: v }); });
}
